validator:
function validate(input) {
  const [{ Activity = [] }] = input;
  const rows = new Map();
  for (const [machine, process, type, time] of Activity) {
    if (machine === null || process === null || time === null) return 'Every row needs a machine_id, a process_id and a timestamp.';
    if (type !== 'start' && type !== 'end') return `activity_type ${type} is not start or end.`;
    const key = `${machine}/${process}`;
    const pair = rows.get(key) ?? {};
    if (pair[type] !== undefined) return `Machine ${machine} has two ${type} rows for process ${process}.`;
    pair[type] = time;
    rows.set(key, pair);
  }
  for (const [key, pair] of rows) {
    if (pair.start === undefined || pair.end === undefined) return `Process ${key} needs both a start and an end row.`;
    if (pair.start > pair.end) return `Process ${key} ends before it starts.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  // Small cases hold at most 4 processes (8 rows); large ones 1,000 processes over 50 machines.
  const processCount = small ? Math.floor(rand() * 5) : 1000;
  const machineCount = small ? 1 + Math.floor(rand() * 3) : 50;
  const byMachine = new Map();
  for (let i = 0; i < processCount; i++) {
    const machine = small ? Math.floor(rand() * machineCount) * 2 : i % machineCount;
    const spans = byMachine.get(machine) ?? [];
    byMachine.set(machine, spans);
    // Times are whole thousandths of a second; process ids restart on every machine, so they collide across machines.
    const start = Math.floor(rand() * (small ? 6000 : 1000000));
    const length = rand() < 0.15 ? 0 : Math.floor(rand() * (small ? 3000 : 50000));
    spans.push([spans.length, start, length]);
  }
  const Activity = [];
  for (const [machine, spans] of byMachine) {
    // An average exactly halfway between two thousandths would make rounding depend on float noise; lengthen one process.
    const total = spans.reduce((sum, [, , length]) => sum + length, 0);
    if (2 * (total % spans.length) === spans.length) spans[0][2] += 1;
    for (const [process, start, length] of spans) {
      Activity.push([machine, process, 'start', start / 1000], [machine, process, 'end', (start + length) / 1000]);
    }
  }
  for (let i = Activity.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Activity[i], Activity[j]] = [Activity[j], Activity[i]]; }
  return [{ Activity }];
}
